<?php require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/auth.php'; require_once __DIR__.'/includes/functions.php'; if(current_user()){redirect('/aasra/'.current_user()['role'].'/dashboard.php');} $title='Login'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $email=post('email');$pass=$_POST['password']??''; $s=$pdo->prepare("SELECT id,name,email,password,role,status FROM users WHERE email=? LIMIT 1");$s->execute([$email]);$u=$s->fetch(); if(!$u||$u['status']!=='Active'||!password_verify($pass,$u['password']))$error='Invalid email or password.'; else { login_user($u); redirect('/aasra/'.$u['role'].'/dashboard.php'); }} include __DIR__.'/includes/header.php'; ?><div class="container py-5"><div class="row justify-content-center"><div class="col-md-6 col-lg-5"><div class="service-card p-4"><h2>Welcome back</h2><p class="text-secondary">Login to your AASRA account.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" data-validate class="needs-validation" novalidate><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label">Email</label><input name="email" type="email" class="form-control form-control-lg" required></div><div class="mb-3"><label class="form-label">Password</label><input name="password" type="password" class="form-control form-control-lg" required></div><button class="btn btn-success w-100 btn-lg">Login</button></form><p class="mt-3 mb-0">No account? <a href="/aasra/register.php">Register</a></p></div></div></div></div><?php include __DIR__.'/includes/footer.php'; ?>
